fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> 
    //@ requires 1 <= k && k < list.len()
    //@ ensures result.len() == list.len() - 1
    //@ ensures forall |i: usize| i < k - 1 ==> result[i] == list[i]
    //@ ensures forall |i: usize| i >= k - 1 && i < result.len() ==> result[i] == list[i + 1]
    //@ ensures forall |x: int| (|count_in_vec(x, result)| == |count_in_vec(x, list)| - if x == list[k-1] { 1 } else { 0 })
{
    // Since k is 1-based and guaranteed to be at least 1 and less than list.len(),
    // we remove the element at index k-1 (0-based)
    let mut new_list = Vec::with_capacity(list.len() - 1);

    // Append all elements before the (k-1)-th index
    new_list.extend_from_slice(&list[..k-1]);
    // Append all elements after the (k-1)-th index
    new_list.extend_from_slice(&list[k..]);

    new_list
}

// Helper specification-only function counting occurrences of x in a vector
#[verifier::spec]
fn count_in_vec(x: int, v: &Vec<i32>) -> nat {
    let mut count: nat = 0;
    let mut i: usize = 0;
    while i < v.len() {
        if v[i] == x {
            count = count + 1;
        }
        i = i + 1;
    }
    count
}